import asyncio, os, signal, sys

variant = sys.argv[1]
clean = sys.argv[2]
ready = sys.argv[3]

def log(s):
    with open(clean, "a") as f:
        f.write(s + "\n"); f.flush()

async def run_tasks(tasks, max_concurrent):
    sem = asyncio.Semaphore(max_concurrent)
    async def one(job):
        async with sem:
            await job()
    running = [asyncio.ensure_future(one(j)) for j in tasks]
    try:
        await asyncio.gather(*running)
    except BaseException:
        for f in running:
            if not f.done():
                f.cancel()
        if variant == "shieldloop":
            drain = asyncio.gather(*running, return_exceptions=True)
            while True:
                try:
                    await asyncio.shield(drain)
                    break
                except asyncio.CancelledError:
                    if all(f.done() for f in running):
                        break
                    for f in running:
                        if not f.done():
                            f.cancel()
        elif variant == "plain":
            await asyncio.gather(*running, return_exceptions=True)
        elif variant == "shieldonce":
            try:
                await asyncio.shield(asyncio.gather(*running, return_exceptions=True))
            except asyncio.CancelledError:
                pass
        raise

def mk(i):
    async def job():
        log(f"started {i}")
        try:
            await asyncio.sleep(30)
        finally:
            log(f"cleaned {i}")
    return job

async def main():
    async def sig():
        await asyncio.sleep(0.4)
        with open(ready, "w") as f: f.write("r")
    asyncio.ensure_future(sig())
    await run_tasks([mk(i) for i in range(8)], 3)

asyncio.run(main())

